def calculate_stock_volatility(prices):
    # Dummy implementation for testing
    # (standard deviation of percentage changes)
    if len(prices) < 2:
        return 0.0
    pct_changes = [(prices[i+1] - prices[i]) / prices[i] for i in range(len(prices)-1)]
    mean = sum(pct_changes) / len(pct_changes)
    variance = sum((x - mean) ** 2 for x in pct_changes) / len(pct_changes)
    return variance ** 0.5

